const paths={home:'<path d="m3 11 9-8 9 8v9a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',book:'<path d="M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2z"/>',cup:'<path d="M7 3h10v7a5 5 0 0 1-10 0zM7 5H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4M12 15v5m-5 1h10"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',fire:'<path d="M13 2c1 5-4 6-3 10 3-1 4-3 5-5 5 5 5 8 3 12-3 5-12 3-13-2-1-4 1-6 3-8 0 3 1 4 2 4"/>',gem:'<path d="m7 3-5 6 10 13L22 9l-5-6zm-5 6h20M7 3l5 19 5-19"/>',heart:'<path d="M12 21 3 12C-2 5 7-1 12 6c5-7 14-1 9 6z"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',sound:'<path d="M4 9h4l5-5v16l-5-5H4zm12-2c4 3 4 7 0 10m3-13c6 5 6 11 0 16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="m9 5 7 7-7 7"/>',chart:'<path d="M4 20V10m8 10V4m8 16v-7"/>',flag:'<path d="M5 22V3c5-5 9 5 14 0v10c-5 5-9-5-14 0"/>',chess:'<path d="M7 21h12M8 18h10L17 14l2-7-6-5-2 3-5 5 4 2 2-3v5z"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 9M20 2v6h-6"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.star}</svg>`;
const asset=(name,cls='')=>`<img class="reference-icon ${cls}" src="/reference/${name}.svg" alt="" aria-hidden="true">`;
const bird=(cls='')=>asset('duo',`bird ${cls}`);
const flag=()=>asset('flag','flag');
const pathNodes=(id,chapter=state.chapter)=>courses[id].lessons[chapter]?.structured?[...Array.from({length:Math.ceil(learningSessions(courses[id].lessons[chapter]).length/5)},()=> 'lesson'),'practice','review']:id==='english'?(chapter>=28&&chapter<=30?['lesson','lesson','chest','practice','review']:['lesson','story','lesson','story','radio','practice','chest','story','radio','practice','review']):['lesson','lesson','practice','lesson','chest','lesson','practice','review'];
const nodeLength=(type,node=0,course=state.course,chapter=state.chapter)=>type==='lesson'?nodeSessions(courses[course].lessons[chapter],pathNodes(course,chapter).slice(0,node).filter(t=>t==='lesson').length).length:1;
const nodeKey=(course,chapter,node)=>`${course}:${chapter}:${node}`;
const nodeProgress=(course,chapter,node)=>state.done[course].includes(chapter)?nodeLength(pathNodes(course,chapter)[node],node,course,chapter):state.nodeProgress[nodeKey(course,chapter,node)]||0;
const chapterNumber=i=>courses[state.course].lessons[i]?.level?`${courses[state.course].lessons[i].level} · UNITÀ ${chapterOrder(state.course).indexOf(i)+1}`:state.course==='chess'?`SCACCHI, CAPITOLO ${i+1}`:i>=28&&i<=30?`SEZIONE 1, CAPITOLO ${i-27}`:i>=8&&i<=27?`SEZIONE 2, CAPITOLO ${i-7}`:`CAPITOLI AGGIUNTIVI, ${i<8?i+1:i-22}`;
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Rome'});
const key='lingo-progress-v1';
const initial=()=>({schema:2,course:'english',xp:0,done:{english:[],chess:[]},days:[],daily:{},goal:30,chapter:44,rounds:{english:{},chess:{}},mistakes:[],sessions:{},gems:0});
let state;
try{const s=JSON.parse(localStorage.getItem(key));state=s&&Array.isArray(s.done?.english)&&Array.isArray(s.done?.chess)?{...initial(),...s}:initial();}catch{state=initial();}
state.nodeProgress ||= {};state.memory ||= {};state.assessments ||= {};state.writing ||= {};state.productionChecks ||= {};state.guideRead ||= {};
if(!state.curriculumVersion){state.curriculumVersion=1;state.chapter=state.course==='english'?44:20;}
state.rounds={english:{},chess:{},...state.rounds};state.mistakes ||= [];state.sessions ||= {};state.gems ||= 0;
if(!courses[state.course])state.course='english';
for(const id of ['english','chess'])for(const i of state.done[id])if(state.rounds[id][i]===undefined)state.rounds[id][i]=id==='english'?6:5;
if(!state.schema){state.chapter=Math.max(0,courses[state.course].lessons.findIndex((_,i)=>!state.done[state.course].includes(i)));const legacyCount=state.done.english.length+state.done.chess.length;if(legacyCount&&!Object.keys(state.sessions).length)state.sessions.legacy=legacyCount;state.schema=2;}
let view='learn',session=null;const pathPages={};
const app=document.querySelector('#app'),dialog=document.querySelector('#lesson');
const save=()=>{try{localStorage.setItem(key,JSON.stringify(state));}catch{notify('Salvataggio non disponibile: i progressi resteranno in questa sessione.');}};
function notify(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),3500);}
function streak(){let count=0,d=new Date();state.protectedDays ||= [];const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);const before=new Date();before.setDate(before.getDate()-2);const yesterdayKey=yesterday.toLocaleDateString('en-CA',{timeZone:'Europe/Rome'}),beforeKey=before.toLocaleDateString('en-CA',{timeZone:'Europe/Rome'});if(state.freezes>0&&!state.days.includes(yesterdayKey)&&!state.protectedDays.includes(yesterdayKey)&&state.days.includes(beforeKey)){state.freezes--;state.protectedDays.push(yesterdayKey);save();}if(!state.days.includes(today()))d.setDate(d.getDate()-1);while(state.days.includes(d.toLocaleDateString('en-CA',{timeZone:'Europe/Rome'}))||state.protectedDays.includes(d.toLocaleDateString('en-CA',{timeZone:'Europe/Rome'}))){count++;d.setDate(d.getDate()-1);}return count;}
const chapterOrder=id=>id==='english'?[...englishCurriculum,...Array.from({length:44},(_,i)=>i)]:chessCourseOrder;
const done=()=>state.done[state.course];
const next=()=>chapterOrder(state.course).find(i=>!done().includes(i))??-1;
function render(){
 app.dataset.screen=view;
 const c=courses[state.course],daily=state.daily[today()]||0;
 document.documentElement.style.setProperty('--accent',state.course==='english'?'#1cb0f6':c.color);
 document.documentElement.style.setProperty('--accent-dark',state.course==='english'?'#1899d6':c.dark);
 const nav=[['learn','home','IMPARA'],['sounds','sounds','SUONI'],['practice','practice','RIPASSO'],['league','league','CLASSIFICHE'],['quests','quests','MISSIONI'],['shop','shop','NEGOZIO'],['stats','profile','PROFILO'],['more','more','MOSTRA ALTRO']].filter(([v])=>state.course==='english'||v!=='sounds');
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="Torna al percorso">${asset('logo','wordmark')}${asset('duo','compact-logo')}</a><nav aria-label="Navigazione principale">${nav.map(([v,i,t])=>`<button aria-label="${t}" class="nav-item ${view===v?'active':''}" data-view="${v}">${i==='profile'?'<span class="profile-avatar">G</span>':asset(i)}<span>${t}</span></button>`).join('')}</nav></aside>
 <div class="workspace"><header class="topbar"><div class="course-select"><button class="course-trigger" aria-label="Cambia corso, ${c.name}" aria-expanded="false" aria-controls="course-menu">${state.course==='english'?flag():icon('chess','teal')}</button><div class="course-menu" id="course-menu" hidden>${Object.entries(courses).map(([id,o])=>`<button data-course="${id}" class="${state.course===id?'selected':''}">${id==='english'?flag():icon('chess','teal')}<span>${o.name}</span>${state.course===id?icon('check'):''}</button>`).join('')}</div></div><div class="metrics"><span class="metric orange" title="Giorni consecutivi">${asset('fire')}<b>${streak()}</b></span><span class="metric blue" title="Gemme">${asset('gem')}<b>${state.gems}</b></span><button class="super-badge" data-view="practice" aria-label="Ripasso senza limiti">${asset('super')}</button></div></header>
 <div class="content-grid"><main id="main">${view==='learn'?pathView():view==='practice'?practiceView():view==='quests'?questsView():view==='words'?wordsView():view==='sections'?sectionsView():view==='guide'?guideView():view==='sounds'?soundsView():view==='league'?leagueView():view==='shop'?shopView():view==='more'?moreView():statsView()}</main><aside class="rightbar"><section class="league-card"><h2>Sblocca le classifiche!</h2><div>${asset('league-card')}<p>${Object.values(state.sessions).reduce((a,b)=>a+b,0)<3?`Completa altre ${Math.max(1,3-Object.values(state.sessions).reduce((a,b)=>a+b,0))} lezioni per partecipare alla tua prima classifica!`:'Hai sbloccato le tue statistiche di allenamento.'}</p></div></section><section class="goal-card"><div class="section-heading"><h2>Missioni giornaliere</h2><button class="text-button" data-view="quests">VEDI TUTTE</button></div><div class="goal-body">${asset('goal')}<div><strong>Guadagna ${state.goal} XP</strong><div class="quest-progress"><div class="progress-line"><i style="width:${Math.min(100,daily/state.goal*100)}%"></i><span>${daily} / ${state.goal}</span></div>${asset('goal-chest')}</div></div></div></section><footer class="side-footer"><button data-view="sections">TUTTI I CAPITOLI</button><button data-view="words">PAROLE</button><button id="goal-setting">OBIETTIVO: ${state.goal} XP</button></footer></aside></div></div>
 <nav class="mobile-nav" aria-label="Navigazione mobile">${nav.filter(([v])=>['learn','sounds','practice','quests','stats'].includes(v)).map(([v,i,t])=>`<button data-view="${v}" aria-label="${t}" class="${view===v?'active':''}">${i==='profile'?'<span class="profile-avatar">G</span>':asset(i)}</button>`).join('')}</nav>`;
 app.querySelector('.brand').onclick=e=>{e.preventDefault();view='learn';render();};
 app.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();window.scrollTo({top:0,behavior:'smooth'});});
 const trigger=app.querySelector('.course-trigger'),menu=app.querySelector('#course-menu');trigger.onclick=()=>{menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)positionCourseMenu();};
 app.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>{state.course=b.dataset.course;state.chapter=Math.max(0,next());save();render();});
 app.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.lesson);if(b.dataset.practice==='true')startLesson(i,true);else startLearning(i);});
 app.querySelector('#goal-setting').onclick=()=>{state.goal=({20:30,30:40,40:60,60:20})[state.goal]||30;save();render();notify(`Obiettivo aggiornato: ${state.goal} XP al giorno`);};
 bindExtra();
 app.querySelectorAll('.animated-character').forEach(character=>character.innerHTML=asset(state.course==='chess'?'oscar':'character'));

 app.querySelector('#export-progress')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lingo-progressi.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});
}
function positionCourseMenu(){
 const menu=app.querySelector('#course-menu'),trigger=app.querySelector('.course-trigger');if(!menu||menu.hidden||!trigger)return;
 const rect=trigger.getBoundingClientRect(),v=window.visualViewport,left=v?.offsetLeft||0,top=v?.offsetTop||0,width=v?.width||window.innerWidth,height=v?.height||window.innerHeight,menuWidth=Math.min(256,width-24);
 menu.style.left=`${Math.max(left+12,Math.min(rect.left,left+width-menuWidth-12))}px`;
 menu.style.top=`${Math.max(top+8,Math.min(rect.bottom+8,top+height-128))}px`;
 menu.style.width=`${menuWidth}px`;
}
window.addEventListener('resize',positionCourseMenu);
window.visualViewport?.addEventListener('resize',positionCourseMenu);
window.visualViewport?.addEventListener('scroll',positionCourseMenu);
function pathView(chapterOverride,preview=false){
 const c=courses[state.course],chapter=Math.min(c.lessons.length-1,chapterOverride??state.chapter??0),l=c.lessons[chapter],nodes=pathNodes(state.course,chapter);
 const current=preview?-1:nodes.findIndex((type,j)=>nodeProgress(state.course,chapter,j)<nodeLength(type,j,state.course,chapter));
 const order=chapterOrder(state.course),position=order.indexOf(chapter),following=order[position+1],previous=order[Math.max(0,position-1)];
 const visibleCount=nodes.filter((type,j)=>type!=='lesson'||nodeLength(type,j,state.course,chapter)>0).length;
 const offsets=[0,-44.875,-70,-44.875,0,44.875,70,44.875,0,-44.875,0];
 const total=nodes.reduce((sum,t,j)=>sum+nodeLength(t,j,state.course,chapter),0),completed=nodes.reduce((sum,t,j)=>sum+Math.min(nodeProgress(state.course,chapter,j),nodeLength(t,j,state.course,chapter)),0);
 const visibleNodes=nodes.map((type,j)=>({type,j})).filter(({type,j})=>type!=='lesson'||nodeLength(type,j,state.course,chapter)>0),pageKey=`${state.course}:${chapter}`,pageCount=Math.ceil(visibleNodes.length/3),selectedPage=Math.min(pageCount-1,pathPages[pageKey]??Math.floor(Math.max(0,visibleNodes.findIndex(n=>n.j===current))/3));
 const activityName=type=>({lesson:'Lezioni',practice:'Ripasso',review:l.assessment?'Verifica':'Riepilogo',story:'Storia',radio:'Ascolto',chest:'Gemme'}[type]);
 return `<section class="unit">${preview?'':`<div class="unit-banner"><div><button class="chapter-link" data-view="sections">${asset('back')}${chapterNumber(chapter)}</button><h2>${esc(l.title)}</h2></div><button class="unit-guide" data-guide="${chapter}" aria-label="Guida del capitolo">${asset('guide')}<span>GUIDA</span></button></div>`}${!preview&&l.structured?`<div class="unit-overview"><p>${esc(l.outcome||l.subtitle)}</p><div class="unit-overview-progress"><span>${completed} di ${total} attività completate</span><div class="unit-track" role="progressbar" aria-label="Progresso del capitolo" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${completed}"><i style="width:${completed/total*100}%"></i></div></div></div>`:''}<div class="premium-path ${l.structured?'structured-path':''} ${visibleCount<8?'short-path':''} ${preview?'preview-path':''}">${nodes.map((type,j)=>{
 if(type==='lesson'&&!nodeLength(type,j,state.course,chapter))return '';
 const count=nodeProgress(state.course,chapter,j),complete=count>=nodeLength(type,j,state.course,chapter),active=j===current;
 const glyph={lesson:'star',story:'book',radio:'radio',practice:'practice',review:'cup'}[type];
 return `<div class="premium-stop ${Math.floor(visibleNodes.findIndex(n=>n.j===j)/3)===selectedPage?'mobile-page-current':''} ${type==='chest'?'chest-stop':''}" style="--offset:${offsets[j]}px">${active?`<span class="start-tag">${count?'CONTINUA':'INIZIA'}</span>`:''}<button class="lesson-node ${complete?'complete':active?'current':'locked'} ${type==='chest'?'treasure-node':''}" data-node="${chapter}" data-round="${j}" data-activity="${type}" aria-label="${activityName(type)} ${type==='lesson'?pathNodes(state.course,chapter).slice(0,j+1).filter(x=>x==='lesson').length:''} ${complete?'completata':active?'da iniziare':'da sbloccare'}">${type==='chest'?asset('chest'):complete?icon('check'):asset(glyph==='star'&&active?'star-active':glyph+'-dark')}</button><span class="activity-label ${l.structured?'':'legacy-activity'} ${active?'is-current':''}">${activityName(type)}</span>${active?`<span class="node-ring" style="--node-progress:${count/nodeLength(type,j,state.course,chapter)*100}%"></span>`:''}<div class="node-popover" hidden><strong>${esc(l.title)}</strong><p>${type==='lesson'?(complete?'Ripasso della lezione':`Lezione ${count+1} di ${nodeLength(type,j,state.course,chapter)}`):type==='story'?'Leggi e ascolta una storia':type==='radio'?'Ascolta una conversazione':type==='chest'?'Raccogli le gemme':type==='practice'?'Recupera quello che hai imparato':l.assessment?'Prova senza suggerimenti':'Riepilogo del capitolo'}</p><button class="primary" data-start-node="${j}" ${!active&&!complete?'disabled':''}>${complete?'RIPASSA +5 XP':active?'INIZIA +20 XP':'COMPLETA LE LEZIONI PRECEDENTI'}</button></div></div>`;
 }).join('')}<div class="animated-character" aria-hidden="true"></div><div class="path-friend-dark">${asset(state.course==='chess'?'oscar':'friend-dark')}</div></div>${!preview&&pageCount>1?`<div class="mobile-path-pages"><button class="icon-button" data-path-page="${selectedPage-1}" aria-label="Tappe precedenti" ${selectedPage===0?'disabled':''}>←</button><span>Tappe ${selectedPage*3+1}–${Math.min(visibleNodes.length,selectedPage*3+3)} di ${visibleNodes.length}</span><button class="icon-button" data-path-page="${selectedPage+1}" aria-label="Tappe successive" ${selectedPage===pageCount-1?'disabled':''}>→</button></div>`:''}${preview?'':`<div class="chapter-end ${l.structured?'structured-next':''}">${l.structured?'<span class="next-unit-kicker">IL PROSSIMO PASSO</span>':''}<h2>${c.lessons[following]?.title||'Capitolo completato'}</h2>${following!==undefined?`<button class="outline" data-chapter="${following}">${l.structured?'VAI ALL’UNITÀ SUCCESSIVA':'VUOI SALTARE FINO A QUI?'}</button>`:'<button class="outline" data-view="practice">RIPASSA</button>'}</div>${following!==undefined&&!l.structured?pathView(following,true):''}<div class="chapter-controls"><button class="text-button" data-chapter="${previous}">← PRECEDENTE</button><button class="text-button" data-view="sections">TUTTI I CAPITOLI</button></div>`}</section>`;
}
function soundsView(){return `<h1 class="hub-title">Impara i suoni dell’inglese</h1><p class="muted">Ascolta i suoni e allenati con parole e frasi.</p><div class="sounds-grid">${[['iː','sheep'],['ɪ','ship'],['æ','cat'],['ɑː','car'],['ʌ','cup'],['ʊ','book'],['uː','blue'],['e','bed'],['ə','teacher'],['ɔː','door'],['θ','think'],['ð','this'],['ʃ','shoe'],['tʃ','chess'],['dʒ','job'],['ŋ','sing']].map(([phoneme,word])=>`<button class="sound-tile" data-audio="${word}"><strong>${phoneme}</strong><span>${word}</span>${icon('sound')}</button>`).join('')}</div><button class="primary" data-mode="dictation">ALLENATI CON L’ASCOLTO</button>`;}
function leagueView(){return `<h1 class="hub-title">Classifiche</h1><section class="league-card">${asset('league-card')}<h2>Il tuo allenamento</h2><p>Hai guadagnato ${state.xp} XP e completato ${Object.values(state.sessions).reduce((a,b)=>a+b,0)} sessioni.</p></section><p class="muted">Le classifiche con altri utenti richiedono un servizio condiviso. Qui vengono salvati i tuoi risultati locali.</p><button class="primary" data-view="stats">VEDI I TUOI PROGRESSI</button>`;}
function shopView(){return `<h1 class="hub-title">Negozio</h1><section class="shop-balance">${asset('gem')}<strong>${state.gems} gemme</strong></section><section class="quest-card">${asset('fire')}<div><h2>Congelazione serie</h2><p>Protegge un giorno senza allenamento. Disponibili: ${state.freezes||0}.</p><button class="outline" data-buy-freeze ${state.gems<50?'disabled':''}>50 GEMME</button></div></section><section class="quest-card">${asset('super')}<div><h2>Ripasso senza limiti</h2><p>Ascolto, pronuncia e ripasso degli errori.</p><button class="primary" data-view="practice">VAI AL RIPASSO</button></div></section>`;}
function moreView(){return `<h1 class="hub-title">Altro</h1><div class="section-list"><button class="section-card" data-view="words">${asset('practice')}Parole e frasi ${icon('arrow')}</button><button class="section-card" data-view="sections">${asset('home')}Tutti i capitoli ${icon('arrow')}</button><button class="section-card" data-view="stats">${icon('chart')}Progressi e backup ${icon('arrow')}</button></div>`;}
function practiceView(){const c=courses[state.course];const due=dueQuestions(state.memory,state.course);return `<h1 class="hub-title">Ripasso del giorno</h1><section class="study-card"><h2>Il ripasso che ti serve</h2><p>${due.length?`${due.length} esercizi già studiati da recuperare senza guardare la soluzione.`:'Nessun ripasso in scadenza. Dopo una lezione, gli esercizi tornano a intervalli crescenti.'}</p><button class="primary" data-due ${due.length?'':'disabled'}>RIPASSO PROGRAMMATO</button></section><section class="premium-hero"><div><h2>${state.course==='english'?'Allena la pronuncia':'Allena la tua strategia'}</h2><p>${state.course==='english'?'Migliora la tua pronuncia!':'Una buona mossa alla volta.'}</p><button class="primary" data-mode="${state.course==='english'?'speak':'mixed'}">INIZIA +5 XP</button></div>${bird()}</section><h2 class="subheading">${state.course==='english'?'Conversazione':'Scacchiera'}</h2><div class="hub-grid">${(state.course==='english'?[['speak','sound','Pronuncia','Leggi, ascolta e confronta la tua frase'],['dictation','sound','Ascolto','Seleziona ciò che senti, oppure scrivi']]:[['matchgame','chess','Partita','Sfida un avversario locale'],['stars','star','Cattura le stelle','Risolvi problemi in più mosse']]).map(([mode,glyph,title,sub])=>`<button class="practice-row" data-mode="${mode}"><span><strong>${title}</strong><small>${sub}</small></span>${icon(glyph)}</button>`).join('')}</div><h2 class="subheading">Le tue collezioni</h2><div class="hub-grid"><button class="practice-row" data-view="words"><span><strong>Parole</strong><small>Vocabolario organizzato per capitolo</small></span>${icon('book')}</button>${state.course==='english'?'<button class="practice-row" data-stories><span><strong>Storie</strong><small>Leggi e ascolta una conversazione</small></span>'+icon('book')+'</button>':''}<button class="practice-row" data-mode="errors" ${state.mistakes.filter(x=>x.course===state.course).length?'':'disabled'}><span><strong>Ripassa gli errori</strong><small>${state.mistakes.filter(x=>x.course===state.course).length} esercizi da rivedere</small></span>${icon('refresh')}</button></div><h2 class="subheading">Ripasso libero</h2><div class="practice-list">${c.lessons.map((l,i)=>`<button class="practice-row" data-lesson="${i}" data-practice="true"><span class="practice-symbol">${icon(state.course==='chess'?'chess':'book')}</span><span><strong>${esc(l.title)}</strong><small>${esc(l.subtitle)} · ${l.questions.length} esercizi</small></span>${icon('arrow')}</button>`).join('')}</div>`;}
function statsView(){const total=Object.values(state.sessions).reduce((n,x)=>n+x,0);return `<div class="page-heading"><span class="eyebrow">GUARDA QUANTA STRADA HAI FATTO</span><h1>I piccoli passi<br>lasciano il segno.</h1><p>Ogni numero qui racconta il tuo lavoro.</p></div><div class="stats-grid"><div>${icon('bolt','blue')}<strong>${state.xp}</strong><span>XP guadagnati</span></div><div>${icon('fire','orange')}<strong>${streak()}</strong><span>giorni di serie</span></div><div>${icon('check','green')}<strong>${total}</strong><span>sessioni completate</span></div></div><h2 class="subheading">I tuoi due percorsi</h2>${Object.entries(courses).map(([id,c])=>`<div class="course-progress"><span>${id==='english'?flag():icon('chess','teal')}</span><div><strong>${c.name}</strong><p>${state.done[id].length} di ${c.lessons.length} capitoli completati</p><div class="progress-line"><i style="width:${state.done[id].length/c.lessons.length*100}%;background:${c.color}"></i></div></div></div>`).join('')}<h2 class="subheading">Piccole grandi conquiste</h2><div class="achievements">${[[total>=1,'star','Il primo passo','Completa una lezione'],[total>=5,'cup','Prendi il ritmo','Completa 5 lezioni'],[Object.keys(state.rounds.english).length>0&&Object.keys(state.rounds.chess).length>0,'chess','Doppia curiosità','Prova entrambi i corsi']].map(([ok,i,t,s])=>`<div class="achievement ${ok?'earned':''}">${icon(i)}<div><strong>${t}</strong><small>${ok?'Traguardo raggiunto!':s}</small></div>${ok?icon('check'):icon('lock')}</div>`).join('')}</div><button class="outline export" id="export-progress">ESPORTA I TUOI PROGRESSI</button>`;}
function shuffle(a){const copy=[...a];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]];}return copy;}
function startLesson(index,practice=false,mode="mixed",round=0,learningNode=null){const c=courses[state.course];if(!c.lessons[index])return;
 session={course:state.course,index,practice,firstAnswers:[],questions:makeQuestions(c.lessons[index],mode,round,learningNode),round,mode,originalLength:makeQuestions(c.lessons[index],mode,round,learningNode).length,step:0,errors:0,correct:0,checked:false,selected:null,words:[],choiceOptions:[],finished:false,start:Date.now()};
 const lesson=c.lessons[index];if(lesson.guide&&!practice&&!state.guideRead[`${state.course}:${index}`])renderLessonIntro(lesson);else renderQuestion();dialog.showModal();document.body.classList.add('in-lesson');}
function closeLesson(){game=null;session?.recognizer?.abort();stopPronunciation();dialog.close();document.body.classList.remove('in-lesson');session=null;render();window.scrollTo(0,0);}
dialog.addEventListener('cancel',e=>{e.preventDefault();closeLesson();});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderQuestion(){stopPronunciation();const s=session,q=s.questions[s.step];s.checked=false;s.intro=false;s.questionErrorStart=s.errors;s.selected=null;s.words=[];s.matches=[];s.stars=q.stars?[...q.stars]:[];s.hint=false;s.pairSelection={};s.board=null;s.boardFrom=null;s.moveTo=null;
 const options=q.type==='choice'||q.type==='listen'||q.type==='comprehension'?shuffle([q.it,...shuffle(courses[s.course].lessons[s.index].questions.filter(x=>x.en&&x.it&&!['gap','comprehension','concept'].includes(x.type)).map(x=>x.it).filter(x=>x!==q.it)).slice(0,3)]):[];if(q.type==='comprehension'||q.type==='concept')options.splice(0,options.length,...shuffle(q.options));if(q.type==='picture')options.push(...q.pictures.map(x=>x.word));if(q.type==='gap')options.push(...shuffle(q.options));s.choiceOptions=options;s.bank=['build','dictation'].includes(q.type)?shuffle(q.en.split(' ').map((word,id)=>({word,id}))):[];
 dialog.innerHTML=`<div class="lesson-shell"><header class="lesson-top"><button class="icon-button close-lesson" aria-label="Esci dalla lezione">${icon('close')}</button><div class="lesson-progress"><i style="width:${s.step/s.questions.length*100}%"></i></div><span class="metric red">${icon('heart')}<b>∞</b></span></header><main class="exercise"><span class="exercise-kicker">${courses[s.course].name.toUpperCase()} · ${courses[s.course].lessons[s.index].title.toUpperCase()}</span><h1>${q.type==='chess'?(q.goal==='fork'?'Trova il doppio attacco':q.goal==='mate'?'Trova lo scacco matto':q.goal==='check'?'Metti il re sotto scacco':'Fai la tua mossa'):q.type==='picture'?`Quale di questi è “${q.it}”?`:q.type==='gap'?'Completa la frase':q.type==='concept'?'Applica quello che hai imparato':q.type==='comprehension'?'Comprendi il testo':q.type==='match'?'Abbina le coppie':q.type==='dictation'?'Seleziona ciò che senti':q.type==='speak'?'Leggi questa frase ad alta voce':['build','write'].includes(q.type)?'Scrivi questa frase in inglese':q.type==='listen'?'Ascolta e scegli il significato':'Scegli la traduzione giusta'}</h1>${q.type==='chess'?chessExercise(q):['write','dictation','speak','match','concept','comprehension','picture','gap'].includes(q.type)?extraExercise(q):q.type==='build'?`<div class="phrase-card">${bird()}<div class="speech">${esc(q.it)}</div></div><div class="answer-line" aria-label="La tua frase"><span class="answer-placeholder">Tocca le parole nell’ordine giusto</span></div><div class="word-bank">${s.bank.map(w=>`<button class="word" data-word="${w.id}">${esc(w.word)}</button>`).join('')}</div>`:`<div class="phrase-card">${bird()}<div class="speech"><button class="audio-button" aria-label="Ascolta la frase in inglese">${icon('sound')}</button><span>${q.type==='listen'?'<span class="audio-label">Tocca per ascoltare</span>':esc(q.en)}</span></div></div>${q.type==='listen'?`<button class="text-button transcript">MOSTRA IL TESTO</button><p class="transcript-text" hidden>${esc(q.en)}</p>`:''}<div class="options">${options.map((o,i)=>`<button class="answer-option" data-choice="${i}"><span class="option-number">${i+1}</span>${esc(o)}</button>`).join('')}</div>`}</main><footer class="lesson-bottom"><div class="bottom-inner"><div class="feedback" role="status" aria-live="polite"><span class="feedback-icon"></span><div><h2></h2><p></p></div></div><button class="primary check-answer" disabled>CONTROLLA</button></div></footer></div>`;
 dialog.querySelector('.close-lesson').onclick=closeLesson;
 dialog.querySelector('.check-answer').onclick=checkAnswer;
 dialog.querySelector('.audio-button')?.addEventListener('click',()=>speak(q.en));
 dialog.querySelector('.transcript')?.addEventListener('click',e=>{dialog.querySelector('.transcript-text').hidden=false;e.currentTarget.hidden=true;});
 dialog.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(s.checked)return;s.selected=Number(b.dataset.choice);dialog.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b));dialog.querySelector('.check-answer').disabled=false;});
 dialog.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{if(s.checked)return;s.words.push(Number(b.dataset.word));updateWords();});
 bindExercise(q);
 if(q.type==='chess')setupBoard(q);
 setTimeout(()=>dialog.querySelector('.close-lesson')?.focus(),10);
}
function speak(text){return playEnglish(text,{onError:notify});}
function updateWords(){const s=session;dialog.querySelectorAll('[data-word]').forEach(b=>b.hidden=s.words.includes(Number(b.dataset.word)));dialog.querySelector('.answer-line').innerHTML=s.words.length?s.words.map((id,i)=>`<button class="word" data-remove="${i}">${esc(s.bank.find(w=>w.id===id).word)}</button>`).join(''):'<span class="answer-placeholder">Tocca le parole nell’ordine giusto</span>';dialog.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(s.checked)return;s.words.splice(Number(b.dataset.remove),1);updateWords();});dialog.querySelector('.check-answer').disabled=!s.words.length;}
const pieces={p:'♟',r:'♜',n:'♞',b:'♝',q:'♛',k:'♚'};
function chessExercise(q){
 const piece=q.piece==='alfiere'?'l’alfiere':['torre','regina'].includes(q.piece)?`la ${q.piece}`:`il ${q.piece}`;
 const objective=q.goal==='fork'?'Crea una forchetta: attacca contemporaneamente il re e la torre neri.':q.goal==='stars'?'Raccogli tutte le stelle con il pezzo bianco.':q.goal==='mate'?'Trova una mossa che dia scacco matto.':q.goal==='check'?'Metti il re nero sotto scacco.':q.goal==='capture'?`Cattura il pezzo nero con ${piece} da ${q.from}.`:`Porta ${piece} da ${q.from} sulla casella ${q.to}.`;
 return `<section class="chess-task"><p class="chess-instruction">${objective}</p><p class="chess-rule">${esc(q.goal==='fork'?'Cerca una casa da cui il tuo pezzo attacchi entrambi i bersagli.':q.goal==='check'?'Attacca il re senza lasciare il tuo re sotto scacco.':q.goal==='mate'?'Il re deve essere sotto attacco e non avere alcuna risposta legale.':q.explanation)}</p>${!q.goal?'<span class="target-legend">◎ La casella da raggiungere è contrassegnata sulla scacchiera.</span>':''}</section><div class="chess-area"><div class="board-wrap"><div class="chessboard" aria-label="Scacchiera, seleziona prima il pezzo e poi la destinazione"></div><div class="board-files">${'abcdefgh'.split('').map(x=>`<span>${x}</span>`).join('')}</div></div><div class="board-note">${icon('chess')}<span>Giochi con i bianchi.<br><strong>Prima il pezzo, poi la casella.</strong><br><button class="text-button hint-move">SUGGERIMENTO</button></span></div></div>`;
}
function setupBoard(q){session.board=new Chess(q.fen);renderBoard(q);dialog.querySelector('.hint-move').onclick=()=>{session.hint=true;renderBoard(q);notify(q.goal==='stars'?'Raggiungi una delle caselle con una stella.':`Prova ${q.from} → ${q.to}`);};}
function renderBoard(q){const s=session;const legal=s.boardFrom?s.board.moves({square:s.boardFrom,verbose:true}).map(m=>m.to):[];dialog.querySelector('.chessboard').innerHTML=Array.from({length:64},(_,i)=>{const row=Math.floor(i/8),col=i%8,square='abcdefgh'[col]+(8-row),p=s.board.get(square);return `<button class="square ${(row+col)%2?'dark':'light'} ${s.boardFrom===square?'from':''} ${(!q.goal||s.hint)&&q.to===square&&!s.checked?'destination':''} ${s.moveTo===square?'moved':''}" data-square="${square}" aria-label="${square}${p?`, ${p.color==='w'?'bianco':'nero'} ${p.type}`:''}" ${s.checked?'disabled':''}>${col===0?`<small class="rank">${8-row}</small>`:''}${p&&!(q.goal==='stars'&&p.type==='k')?`<span class="piece ${p.color==='w'?'white':'black'}">${pieces[p.type]}</span>`:legal.includes(square)?'<span class="move-dot"></span>':''}${s.stars.includes(square)?'<span class="collect-star">★</span>':''}${(!q.goal||s.hint)&&q.to===square&&!s.checked?'<span class="target-dot"></span>':''}</button>`;}).join('');
 dialog.querySelectorAll('[data-square]').forEach(b=>b.onclick=()=>{if(s.checked||(s.selected&&q.goal!=='stars'))return;const square=b.dataset.square,p=s.board.get(square);if(p?.color==='w'&&!(q.goal==='stars'&&p.type==='k')){s.boardFrom=square;renderBoard(q);return;}if(!s.boardFrom){notify('Prima seleziona il pezzo bianco.');return;}let move;try{move=s.board.move({from:s.boardFrom,to:square,promotion:'q'});}catch{notify('Questa mossa non è consentita. Cerca una delle caselle indicate.');return;}if(move){s.selected={from:move.from,to:move.to};s.moveTo=move.to;s.boardFrom=null;if(q.goal==='stars'){s.stars=s.stars.filter(x=>x!==move.to);s.board.load(s.board.fen().replace(' b ',' w '));}renderBoard(q);dialog.querySelector('.check-answer').disabled=q.goal==='stars'&&s.stars.length>0;dialog.querySelector('.board-note').innerHTML=`${icon('check')}<span>Mossa ${move.from} → ${move.to}<br><button class="text-button undo-move">CAMBIA MOSSA</button></span>`;dialog.querySelector('.undo-move').onclick=()=>{if(q.goal==='stars')s.board=new Chess(q.fen);else s.board.undo();s.selected=null;s.moveTo=null;s.boardFrom=null;s.stars=q.stars?[...q.stars]:[];renderBoard(q);dialog.querySelector('.check-answer').disabled=true;};}});
}
function checkAnswer(){const s=session;if(s.checked){s.step++;if(s.step===s.questions.length)finish();else renderQuestion();return;}const q=s.questions[s.step];let correct;
 if(q.type==='picture')correct=s.choiceOptions[s.selected]===q.en;else if(q.type==='gap')correct=s.choiceOptions[s.selected]===q.answer;else if(q.type==='stars')correct=false;else if(q.goal==='stars')correct=s.stars.length===0;else if(['write','dictation','speak'].includes(q.type))correct=answersEquivalent(s.typed?dialog.querySelector('.typed-answer').value:s.words.map(id=>s.bank.find(w=>w.id===id).word).join(' '),q);else if(q.type==='match')correct=s.matches.length===s.matchPairs.length;else if(q.type==='comprehension'||q.type==='concept')correct=s.choiceOptions[s.selected]===q.options[q.answer];else if(q.type==='chess')correct=chessGoalSatisfied(q,s.board,s.selected);else if(q.type==='build')correct=answersEquivalent(s.words.map(id=>s.bank.find(w=>w.id===id).word).join(' '),q);else correct=s.choiceOptions[s.selected]===q.it;
 if(!q.retry){s.firstAnswers.push(Boolean(correct&&!s.hint&&s.errors===s.questionErrorStart));(s.firstRecords||=[]).push({chapter:q.studyChapter??s.index,correct:Boolean(correct&&!s.hint&&s.errors===s.questionErrorStart)});if(!s.diagnostic)recordAttempt(state.memory,s.course,q.studyChapter??s.index,q,correct&&!s.hint&&s.errors===s.questionErrorStart);}s.checked=true;s.lastCorrect=correct;if(correct){s.correct++;state.mistakes=state.mistakes.filter(x=>!(x.course===s.course&&questionId(x.q)===questionId(q)));}else{s.errors++;if(!state.mistakes.some(x=>x.course===s.course&&questionId(x.q)===questionId(q)))state.mistakes.push({course:s.course,index:q.studyChapter??s.index,q});if(!s.assessment)s.questions.push({...q,retry:true});}save();
 const footer=dialog.querySelector('.lesson-bottom');footer.classList.add(correct?'success':'failure');dialog.querySelector('.feedback-icon').innerHTML=icon(correct?'check':'close');dialog.querySelector('.feedback h2').textContent=correct?['Ben fatto!','Proprio così!','Ottimo lavoro!'][s.step%3]:'Ci sei quasi. Impariamo insieme.';dialog.querySelector('.feedback p').textContent=q.explanation?q.explanation:correct?'Un altro piccolo passo avanti.':`Soluzione: ${['build','write','dictation','speak'].includes(q.type)?q.en:['concept','comprehension'].includes(q.type)?q.options[q.answer]:q.type==='picture'?q.en:q.type==='gap'?q.answer:q.it}`;
 const btn=dialog.querySelector('.check-answer');btn.textContent='CONTINUA';btn.disabled=false;btn.focus();
 if(q.type==='chess'&&q.goal!=='stars'&&!correct){s.board=new Chess(q.fen);s.board.move({from:q.from,to:q.to,promotion:'q'});s.moveTo=q.to;s.boardFrom=null;renderBoard(q);}
 dialog.querySelectorAll('[data-choice],[data-word],[data-remove],.undo-move').forEach(b=>b.disabled=true);
}
function finish(){const s=session;if(s.finished)return;s.finished=true;if(s.assessment){finishAssessment();return;}const repeated=s.pathKey?nodeProgress(s.course,s.index,s.pathNode)>=nodeLength(pathNodes(s.course,s.index)[s.pathNode],s.pathNode,s.course,s.index):(state.rounds[s.course][s.index]||0)>s.round;const award=s.practice||repeated?5:20;
 if(s.pathKey&&!s.practice){state.nodeProgress[s.pathKey]=(state.nodeProgress[s.pathKey]||0)+1;const allDone=pathNodes(s.course,s.index).every((type,j)=>nodeProgress(s.course,s.index,j)>=nodeLength(type,j,s.course,s.index));if(allDone&&!state.done[s.course].includes(s.index))state.done[s.course].push(s.index);}
 if(!s.practice)state.rounds[s.course][s.index]=Math.max(state.rounds[s.course][s.index]||0,s.round+1);
 state.sessions[today()]=(state.sessions[today()]||0)+1;state.gems+=s.practice?1:5;state.xp+=award;state.daily[today()]=(state.daily[today()]||0)+award;if(!state.days.includes(today()))state.days.push(today());save();
 const seconds=Math.round((Date.now()-s.start)/1000);dialog.innerHTML=`<div class="finish-screen"><div class="sunburst">${icon('cup')}</div>${bird()}<span class="eyebrow">UN PASSO IN PIÙ</span><h1>Lezione completata!</h1><p>${s.errors===0?'Tutte giuste. Sei stato bravissimo!':'Ogni errore ti insegna qualcosa. Continua così!'}</p><div class="finish-stats"><div>${icon('bolt')}<strong>+${award} XP</strong><span>Esperienza</span></div><div>${icon('target')}<strong>${s.correct}/${s.questions.length}</strong><span>Risposte corrette</span></div><div>${icon('check')}<strong>${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}</strong><span>Tempo dedicato</span></div></div><button class="primary finish-button">TORNA AL PERCORSO</button></div>`;dialog.querySelector('.finish-button').onclick=()=>{view='learn';closeLesson();};dialog.querySelector('.finish-button').focus();}
document.addEventListener('keydown',e=>{if(!dialog.open||!session||session.finished||session.intro)return;if(e.key==='Enter'&&!['BUTTON','TEXTAREA'].includes(e.target.tagName)){const b=dialog.querySelector('.check-answer');if(!b.disabled){e.preventDefault();b.click();}}if(/^[1-4]$/.test(e.key)&&!session.checked)dialog.querySelector(`[data-choice="${Number(e.key)-1}"]`)?.click();});
document.addEventListener('click',e=>{const m=document.querySelector('#course-menu');if(m&&!e.target.closest('.course-select')){m.hidden=true;document.querySelector('.course-trigger')?.setAttribute('aria-expanded','false');}});

function sectionsView(){const c=courses[state.course],order=chapterOrder(state.course),groups=[...new Set(order.map(i=>c.lessons[i].level||'Biblioteca aggiuntiva'))];return `<h1 class="hub-title">Il corso di ${c.name.toLowerCase()}</h1><p class="muted">${state.course==='english'?'A1–C1: livelli obiettivo, senza certificazione.':'Da zero ai fondamentali intermedi, senza Elo attribuito.'} ${c.lessons.length} capitoli originali. I progressi precedenti sono conservati.</p><div class="study-card"><h2>Spiegazione → pratica → verifica → ripasso</h2><p>Ogni unità strutturata distingue esercizi guidati, prova senza suggerimenti e compito autonomo. La verifica dei quiz non certifica il livello di lingua o la forza di gioco.</p><button class="outline" data-diagnostic>ORIENTATI NEL CORSO</button></div>${groups.map((group,g)=>`<details class="course-level" ${g===0?'open':''}><summary>${esc(group)} <small>${order.filter(i=>(c.lessons[i].level||'Biblioteca aggiuntiva')===group).length} capitoli</small></summary><div class="section-list">${order.filter(i=>(c.lessons[i].level||'Biblioteca aggiuntiva')===group).map(i=>{const l=c.lessons[i],result=state.assessments[`${state.course}:${i}`];return `<article class="course-unit"><button class="section-card" data-chapter="${i}"><span class="section-number">${order.indexOf(i)+1}</span><span><strong>${esc(l.title)}</strong><small>${esc(l.subtitle)}</small><small>${state.done[state.course].includes(i)?'Percorso completato · ':''}${result?`Verifica: ${Math.round(result.score*100)}%${result.passed?' · superata':' · da rivedere'}`:'Verifica non svolta'}</small></span>${icon('arrow')}</button>${l.guide?`<div class="unit-actions"><button class="text-button" data-guide="${i}">GUIDA E COMPITO</button>${l.assessment?`<button class="text-button" data-assessment="${i}">VERIFICA</button>`:''}</div>`:''}</article>`;}).join('')}</div></details>`).join('')}`;}

function questsView(){const xp=state.daily[today()]||0,count=state.sessions[today()]||0;return `<h1 class="hub-title">Missioni giornaliere</h1><p class="muted">Un po’ di pratica, ogni giorno. I progressi si aggiornano quando termini una sessione.</p>${[[xp,30,'Guadagna 30 XP','bolt'],[count,3,'Completa 3 sessioni','book'],[state.mistakes.filter(x=>x.course===state.course).length?0:1,1,'Tieni vuoto il ripasso errori','check']].map(([value,target,label,glyph])=>`<section class="quest-card">${icon(glyph)}<div><h2>${label}</h2><div class="progress-line"><i style="width:${Math.min(100,value/target*100)}%"></i></div><small>${Math.min(value,target)} / ${target}${value>=target?' · Completata!':''}</small></div></section>`).join('')}<button class="primary" data-view="learn">CONTINUA IL PERCORSO</button>`;}
function wordsView(){const c=courses[state.course];return `<h1 class="hub-title">${state.course==='english'?'Parole e frasi':'La tua guida agli scacchi'}</h1><label class="search-label">Cerca nel tuo vocabolario<input id="word-search" class="typed-answer" placeholder="Cerca una parola o un argomento" type="search"></label><div class="vocabulary">${c.lessons.map(l=>`<details class="vocab-chapter"><summary>${esc(l.title)}</summary>${l.questions.map(q=>`<div class="vocab-row" data-search="${esc((q.en||q.piece||'')+' '+(q.it||q.explanation||''))}">${state.course==='english'?`<button class="icon-button" data-audio="${esc(q.en)}" aria-label="Ascolta ${esc(q.en)}">${icon('sound')}</button><span><strong>${esc(q.en)}</strong><small>${esc(q.it)}</small></span>`:`<span><strong>${esc(q.piece||q.prompt||l.title)}</strong><small>${esc(q.explanation||l.guide?.rule||'')}</small></span>`}</div>`).join('')}</details>`).join('')}</div>`;}
function bindExtra(){
 app.querySelectorAll('[data-path-page]').forEach(b=>b.onclick=()=>{pathPages[`${state.course}:${state.chapter}`]=Number(b.dataset.pathPage);render();});
 app.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{state.chapter=Number(b.dataset.chapter);save();view='learn';render();window.scrollTo(0,0);});
 app.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>{const pop=b.parentElement.querySelector('.node-popover'),wasOpen=!pop.hidden;app.querySelectorAll('.node-popover').forEach(p=>p.hidden=true);pop.hidden=wasOpen;});
 app.querySelectorAll('[data-start-node]').forEach(b=>b.onclick=()=>{const j=Number(b.dataset.startNode),i=state.chapter,type=pathNodes(state.course)[j],k=nodeKey(state.course,i,j),count=nodeProgress(state.course,i,j),practice=count>=nodeLength(type,j,state.course,i);
 if(type==='chest'){if(!practice){state.gems+=15;state.nodeProgress[k]=1;save();render();notify('Hai raccolto 15 gemme!');}return;}
 if(type==='story')startStory((i+j)%stories.length,i,j,practice);else if(type==='lesson'){const ordinal=pathNodes(state.course,i).slice(0,j).filter(t=>t==='lesson').length;const total=nodeLength(type,j,state.course,i);startLesson(i,practice,'mixed',Math.min(count,total-1),ordinal);}else if(type==='review'&&courses[state.course].lessons[i].assessment){startAssessment(i);return;}else startLesson(i,practice,type==='radio'?'dictation':'mixed',0);
 session.pathNode=j;session.pathKey=k;
 });
 app.querySelector('[data-buy-freeze]')?.addEventListener('click',()=>{if(state.gems>=50){state.gems-=50;state.freezes=(state.freezes||0)+1;save();render();}});
 app.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>{state.chapter=Number(b.dataset.guide);view='guide';render();window.scrollTo(0,0);});
 bindStudy();
 app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{const mode=b.dataset.mode,index=Math.min(courses[state.course].lessons.length-1,state.chapter||0);if(mode==='matchgame')return startGame();if(mode==='stars')return startLesson(8,true);if(mode==='errors'){const errors=state.mistakes.filter(x=>x.course===state.course);if(!errors.length)return;startLesson(errors[0].index,true);session.questions=errors.map(x=>({...x.q,studyChapter:x.index}));session.originalLength=session.questions.length;renderQuestion();return;}startLesson(index,true,mode);if(state.course==='english'&&['dictation','speak'].includes(mode)){const pool=courses.english.lessons.slice(index,index+5).flatMap(l=>l.questions).filter(q=>q.en&&q.it&&q.en.split(' ').length>=3&&!['concept','comprehension'].includes(q.type));session.questions=shuffle(pool).slice(0,10).map(q=>({...q,type:mode}));session.originalLength=session.questions.length;renderQuestion();}});
 app.querySelector('[data-stories]')?.addEventListener('click',showStories);
 app.querySelectorAll('[data-audio]').forEach(b=>b.onclick=()=>speak(b.dataset.audio));
 app.querySelector('#word-search')?.addEventListener('input',e=>{const term=normalize(e.target.value);app.querySelectorAll('.vocab-chapter').forEach(d=>{let visible=0;d.querySelectorAll('[data-search]').forEach(row=>{row.hidden=!normalize(row.dataset.search).includes(term);if(!row.hidden)visible++;});d.hidden=visible===0;if(term)d.open=true;});});
}
function extraExercise(q){
 if(q.type==='concept')return `<p class="concept-prompt">${esc(q.prompt)}</p><div class="options">${session.choiceOptions.map((o,i)=>`<button class="answer-option" data-choice="${i}"><span class="option-number">${i+1}</span>${esc(o)}</button>`).join('')}</div>`;
 if(q.type==='picture')return `<div class="picture-options">${q.pictures.map((x,i)=>`<button class="answer-option picture-option" data-choice="${i}"><span class="picture-symbol" aria-hidden="true">${x.symbol}</span><span>${esc(x.word)}</span><span class="option-number">${i+1}</span></button>`).join('')}</div>`;
 if(q.type==='gap')return `<p class="gap-prompt">${esc(q.prompt)}</p><div class="options">${session.choiceOptions.map((x,i)=>`<button class="answer-option" data-choice="${i}">${esc(x)}</button>`).join('')}</div>`;
 if(q.type==='comprehension')return `<div class="story-dialogue">${q.lines.map(([name,line])=>`<div><strong>${esc(name)}</strong><p>${esc(line)}</p></div>`).join('')}</div><button class="text-button story-audio">${icon('sound')} ASCOLTA ${q.lines.length===1?'IL TESTO':'IL DIALOGO'}</button><h2>${esc(q.question)}</h2><div class="options">${session.choiceOptions.map((o,i)=>`<button class="answer-option" data-choice="${i}">${esc(o)}</button>`).join('')}</div>`;
 if(q.type==='match'){
  const pool=[q,...shuffle(session.questions.filter(x=>x.en&&x.it&&!['comprehension','concept','gap'].includes(x.type)&&x.en!==q.en)).slice(0,3)];session.matchPairs=pool;
  return `<div class="pair-grid"><div>${shuffle(pool.map((x,i)=>({x,i}))).map(({x,i})=>`<button class="pair" data-pair="${i}" data-side="en">${esc(x.en)}</button>`).join('')}</div><div>${shuffle(pool.map((x,i)=>({x,i}))).map(({x,i})=>`<button class="pair" data-pair="${i}" data-side="it">${esc(x.it)}</button>`).join('')}</div></div><p class="pair-status" aria-live="polite">Abbina una frase inglese alla sua traduzione.</p>`;
 }
 session.typed=q.type!=='dictation';
 return `<div class="phrase-card">${q.type==='dictation'?'':bird()}<div class="speech"><button class="audio-button" aria-label="Ascolta la frase">${icon('sound')}</button>${q.type==='dictation'?'<button class="text-button slow-audio" aria-label="Ascolta lentamente">0.75×</button>':`<span>${esc(q.type==='speak'?q.en:q.it)}</span>`}</div></div>${q.type==='dictation'?`<div class="answer-line" aria-label="La tua frase"><span class="answer-placeholder">Seleziona ciò che senti</span></div><div class="word-bank">${session.bank.map(w=>`<button class="word" data-word="${w.id}">${esc(w.word)}</button>`).join('')}</div><button class="text-button toggle-keyboard">USA LA TASTIERA</button>`:''}<label class="typed-wrap" ${session.typed?'':'hidden'}><span>${q.type==='speak'?'Trascrizione oppure risposta scritta':'La tua risposta in inglese'}</span><textarea class="typed-answer" rows="3" autocapitalize="off" spellcheck="false" placeholder="Scrivi in inglese…"></textarea></label>${q.type==='speak'?'<button class="outline record-voice">INIZIA A PARLARE</button><p class="muted voice-status" role="status">Il riconoscimento dipende dal browser. Se non disponibile, scrivi la frase.</p>':''}`;
}
function bindExercise(q){
 dialog.querySelector('.story-audio')?.addEventListener('click',()=>speak(q.lines.map(x=>x[1]).join(' ')));
 dialog.querySelector('.slow-audio')?.addEventListener('click',()=>speakSlow(q.en));
 const field=dialog.querySelector('.typed-answer');field?.addEventListener('input',()=>dialog.querySelector('.check-answer').disabled=!field.value.trim());
 dialog.querySelector('.toggle-keyboard')?.addEventListener('click',e=>{session.typed=!session.typed;dialog.querySelector('.typed-wrap').hidden=!session.typed;dialog.querySelector('.answer-line').hidden=session.typed;dialog.querySelector('.word-bank').hidden=session.typed;e.currentTarget.textContent=session.typed?'USA LE PAROLE':'USA LA TASTIERA';dialog.querySelector('.check-answer').disabled=session.typed?!field.value.trim():!session.words.length;if(session.typed)field.focus();});
 dialog.querySelector('.record-voice')?.addEventListener('click',()=>{
  const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition,status=dialog.querySelector('.voice-status');if(!Recognition){status.textContent='Riconoscimento vocale non disponibile qui: ascolta la frase e trascrivila.';field.focus();return;}
  const r=new Recognition();session.recognizer?.abort();session.recognizer=r;r.lang='en-US';r.interimResults=false;r.onresult=e=>{field.value=e.results[0][0].transcript;field.dispatchEvent(new Event('input'));status.textContent='Frase riconosciuta. Controlla e conferma la trascrizione.';};r.onerror=()=>{status.textContent='Microfono non disponibile o ascolto interrotto. Puoi scrivere la frase.';};r.onend=()=>{dialog.querySelector('.record-voice')?.removeAttribute('disabled');};try{r.start();status.textContent='In ascolto… il servizio vocale del browser elabora la registrazione.';dialog.querySelector('.record-voice').disabled=true;}catch{status.textContent='Non è stato possibile avviare il microfono. Scrivi la frase.';}
 });
 dialog.querySelectorAll('[data-pair]').forEach(b=>b.onclick=()=>{if(session.checked||b.disabled)return;const side=b.dataset.side,id=Number(b.dataset.pair);dialog.querySelectorAll(`[data-side="${side}"]`).forEach(x=>x.classList.remove('selected'));b.classList.add('selected');session.pairSelection ||= {};session.pairSelection[side]=id;const pick=session.pairSelection;if(pick.en!==undefined&&pick.it!==undefined){if(pick.en===pick.it){session.matches.push(pick.en);dialog.querySelectorAll(`[data-pair="${pick.en}"]`).forEach(x=>{x.disabled=true;x.classList.add('paired');x.classList.remove('selected');});dialog.querySelector('.pair-status').textContent=`${session.matches.length} di ${session.matchPairs.length} coppie abbinate`;}else{session.errors++;dialog.querySelector('.pair-status').textContent='Queste due frasi non corrispondono. Riprova.';dialog.querySelectorAll('.pair.selected').forEach(x=>x.classList.remove('selected'));}session.pairSelection={};dialog.querySelector('.check-answer').disabled=session.matches.length!==session.matchPairs.length;}});
}
function speakSlow(text){return playEnglish(text,{slow:true,onError:notify});}
function showStories(){dialog.innerHTML=`<div class="story-library"><button class="icon-button close-library" aria-label="Chiudi storie">${icon('close')}</button><h1>Le tue storie</h1><p>Ascolta, leggi e rispondi.</p>${stories.map((s,i)=>`<button class="practice-row" data-story="${i}"><strong>${esc(s.title)}</strong>${icon('book')}</button>`).join('')}</div>`;dialog.showModal();document.body.classList.add('in-lesson');dialog.querySelector('.close-library').onclick=closeLesson;dialog.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{dialog.close();startStory(Number(b.dataset.story));});}
function startStory(id,index=0,round=0,practice=true){const story=stories[id];startLesson(index,practice);session.round=round;session.questions=[{...story,type:'comprehension',en:story.title,it:story.options[story.answer]}];session.originalLength=1;renderQuestion();}

function startLearning(index){state.chapter=index;const nodes=pathNodes(state.course,index),j=nodes.findIndex((t,n)=>t==='lesson'&&nodeProgress(state.course,index,n)<nodeLength(t,n,state.course,index));if(j<0){startLesson(index,true);return;}const ordinal=nodes.slice(0,j).filter(t=>t==='lesson').length;startLesson(index,false,'mixed',nodeProgress(state.course,index,j),ordinal);session.pathNode=j;session.pathKey=nodeKey(state.course,index,j);}
function guideMarkup(l){return `<span class="eyebrow">${esc(l.level||'GUIDA')} · OBIETTIVO</span><h1>${esc(l.title)}</h1><p class="guide-outcome">${esc(l.outcome||l.subtitle)}</p><section class="study-card"><h2>Come funziona</h2><p>${esc(l.guide.rule)}</p></section><section class="study-card"><h2>Attenzione a questo errore</h2><p>${esc(l.guide.trap)}</p></section>${l.guide.examples.length?`<section class="study-card"><h2>Due esempi spiegati</h2>${l.guide.examples.map(x=>`<p><strong>${esc(x.en)}</strong><br><span class="muted">${esc(x.it)}</span><button class="icon-button" data-audio="${esc(x.en)}" aria-label="Ascolta esempio">${icon('sound')}</button></p>`).join('')}</section>`:''}`;}
function renderLessonIntro(l){session.intro=true;dialog.innerHTML=`<div class="guide-dialog"><button class="icon-button close-lesson" aria-label="Esci">${icon('close')}</button>${guideMarkup(l)}<button class="primary" data-begin-study>HO CAPITO, PROVIAMO</button></div>`;dialog.querySelector('.close-lesson').onclick=closeLesson;dialog.querySelector('[data-begin-study]').onclick=()=>{state.guideRead[`${session.course}:${session.index}`]=true;save();renderQuestion();};dialog.querySelectorAll('[data-audio]').forEach(b=>b.onclick=()=>speak(b.dataset.audio));}
function guideView(){const l=courses[state.course].lessons[state.chapter];if(!l.guide)return wordsView();const k=`${state.course}:${state.chapter}`;return `<div class="course-guide"><button class="text-button" data-view="learn">← TORNA AL PERCORSO</button>${guideMarkup(l)}<section class="study-card"><h2>Ora usalo davvero</h2><p>${esc(l.guide.production)}</p><label class="search-label">Il tuo testo o l’analisi della partita<textarea id="production-text" class="typed-answer" rows="7" placeholder="Scrivi qui. Il lavoro viene salvato sul tuo dispositivo.">${esc(state.writing[k]||'')}</textarea></label><p class="muted">Autovalutazione: questi criteri non assegnano un voto automatico al parlato o al testo.</p>${l.guide.rubric.map((label,i)=>`<label class="rubric-row"><input type="checkbox" data-rubric="${i}" ${state.productionChecks[k]?.[i]?'checked':''}><span>${esc(label)}</span></label>`).join('')}<p class="muted" id="writing-status" role="status">${state.writing[k]?'Testo salvato sul dispositivo.':'Il testo resta privato sul dispositivo.'}</p></section><div class="guide-actions"><button class="primary" data-lesson="${state.chapter}">ALLENA IL CAPITOLO</button>${l.assessment?`<button class="outline" data-assessment="${state.chapter}">PROVA LA VERIFICA</button>`:''}</div></div>`;}
function startAssessment(index){const l=courses[state.course].lessons[index];if(!l.assessment?.length)return;startLesson(index,true);session.questions=l.assessment.map(q=>({...q}));session.originalLength=session.questions.length;session.assessment=true;session.firstAnswers=[];renderQuestion();}
function finishAssessment(){const s=session,result=assessmentResult(s.firstAnswers),levelScores=s.diagnostic?[...new Set(s.firstRecords.map(x=>courses[s.course].lessons[x.chapter].level))].map(level=>{const a=s.firstRecords.filter(x=>courses[s.course].lessons[x.chapter].level===level);return {level,score:a.filter(x=>x.correct).length/a.length};}):[],k=`${s.course}:${s.index}`;if(!s.diagnostic){state.assessments[k]={...result,date:Date.now(),answers:s.firstAnswers.length};if(result.passed){const j=pathNodes(s.course,s.index).indexOf('review');state.nodeProgress[nodeKey(s.course,s.index,j)]=1;if(pathNodes(s.course,s.index).every((type,n)=>nodeProgress(s.course,s.index,n)>=nodeLength(type,n,s.course,s.index))&&!state.done[s.course].includes(s.index))state.done[s.course].push(s.index);}}save();dialog.innerHTML=`<div class="finish-screen"><div class="sunburst">${icon('target')}</div><h1>${s.diagnostic?'Orientamento completato':result.passed?'Verifica superata':'Rivediamo il capitolo'}</h1><p><strong>${Math.round(result.score*100)}%</strong> di risposte corrette al primo tentativo.</p><p>${s.diagnostic?'Questa prova breve ti aiuta a scegliere dove iniziare; non misura né certifica un livello.':result.passed?'Hai recuperato questi contenuti senza suggerimenti. Il compito autonomo e il ripasso differito completano il lavoro.':'Rileggi la guida, prova gli esercizi e torna alla verifica. Gli errori sono nel ripasso.'}</p>${s.diagnostic?`<div class="diagnostic-results">${levelScores.map(x=>`<p>${esc(x.level)} · ${Math.round(x.score*100)}% sul campione breve</p>`).join('')}</div><p>Inizia dal primo gruppo in cui hai avuto difficoltà. Verifica anche ascolto, scrittura libera e interazione.</p>`:''}<p class="muted">Nessun livello CEFR o Elo viene assegnato da questa prova.</p><button class="primary finish-button">${s.diagnostic?'VEDI IL CORSO':'CONTINUA'}</button></div>`;dialog.querySelector('.finish-button').onclick=()=>{closeLesson();view=s.diagnostic?'sections':'guide';state.chapter=s.index;render();};}
function startDiagnostic(){const indexes=state.course==='english'?englishCurriculum:chessCourseOrder.filter(i=>courses.chess.lessons[i].assessment);const selected=state.course==='english'?[...new Set(indexes.map(i=>courses.english.lessons[i].level))].map(level=>indexes.find(i=>courses.english.lessons[i].level===level)):indexes.filter((_,i)=>i%4===0);startAssessment(selected[0]);session.questions=selected.flatMap(i=>courses[state.course].lessons[i].assessment.slice(0,2).map(q=>({...q,studyChapter:i})));session.originalLength=session.questions.length;session.diagnostic=true;renderQuestion();}
function bindStudy(){const k=`${state.course}:${state.chapter}`;app.querySelector('#production-text')?.addEventListener('input',e=>{state.writing[k]=e.target.value;save();app.querySelector('#writing-status').textContent='Testo salvato sul dispositivo.';});app.querySelectorAll('[data-rubric]').forEach(b=>b.onchange=()=>{state.productionChecks[k]||={};state.productionChecks[k][b.dataset.rubric]=b.checked;save();});app.querySelectorAll('[data-assessment]').forEach(b=>b.onclick=()=>startAssessment(Number(b.dataset.assessment)));app.querySelector('[data-diagnostic]')?.addEventListener('click',startDiagnostic);app.querySelector('[data-due]')?.addEventListener('click',()=>{const due=dueQuestions(state.memory,state.course);if(!due.length)return;startLesson(due[0].chapter,true);session.questions=due.map(x=>({...x.q,studyChapter:x.chapter}));session.originalLength=session.questions.length;renderQuestion();});}

let game=null;
function startGame(){session=null;game={board:new Chess(),selected:null,busy:false,history:[],level:2};dialog.innerHTML=`<div class="game-shell"><header><button class="icon-button close-game" aria-label="Esci dalla partita">${icon('close')}</button><h1>Una partita di scacchi</h1></header><p class="muted">Avversario locale · tu giochi con i bianchi</p><div class="chessboard game-board"></div><p class="game-status" aria-live="polite"></p><div class="game-actions"><button class="outline undo-game">ANNULLA TURNO</button><button class="outline restart-game">NUOVA PARTITA</button></div><details><summary>Le mosse della partita</summary><p class="game-history"></p></details></div>`;dialog.showModal();document.body.classList.add('in-lesson');dialog.querySelector('.close-game').onclick=()=>{game=null;closeLesson();};dialog.querySelector('.restart-game').onclick=()=>{game.board.reset();game.selected=null;game.busy=false;drawGame();};dialog.querySelector('.undo-game').onclick=()=>{if(game.busy)return;if(game.board.turn()==='w')game.board.undo();game.board.undo();game.selected=null;drawGame();};drawGame();}
function drawGame(){const g=game;if(!g)return;const board=g.board,legal=g.selected?board.moves({square:g.selected,verbose:true}).map(x=>x.to):[];dialog.querySelector('.game-board').innerHTML=Array.from({length:64},(_,i)=>{const row=Math.floor(i/8),col=i%8,sq='abcdefgh'[col]+(8-row),p=board.get(sq);return `<button class="square ${(row+col)%2?'dark':'light'} ${sq===g.selected?'from':''}" data-game-square="${sq}" aria-label="${sq}${p?' '+p.color+' '+p.type:''}" ${g.busy||board.isGameOver()?'disabled':''}>${p?`<span class="piece ${p.color==='w'?'white':'black'}">${pieces[p.type]}</span>`:legal.includes(sq)?'<span class="move-dot"></span>':''}</button>`;}).join('');dialog.querySelector('.game-status').textContent=board.isCheckmate()?(board.turn()==='w'?'Scacco matto. Vince l’avversario.':'Scacco matto. Hai vinto!'):board.isGameOver()?'Partita terminata in parità.':g.busy?'L’avversario sta pensando…':board.isCheck()?'Sei sotto scacco. Proteggi il re!':'Tocca a te. Scegli un pezzo bianco.';dialog.querySelector('.game-history').textContent=board.pgn()||'Nessuna mossa ancora.';dialog.querySelectorAll('[data-game-square]').forEach(b=>b.onclick=()=>{if(g.busy||board.isGameOver())return;const sq=b.dataset.gameSquare,p=board.get(sq);if(p?.color==='w'){g.selected=sq;drawGame();return;}if(!g.selected)return;try{board.move({from:g.selected,to:sq,promotion:'q'});}catch{return notify('Mossa non consentita.');}g.selected=null;if(board.isGameOver()){drawGame();return;}g.busy=true;drawGame();setTimeout(()=>{if(game!==g||!g.busy)return;const best=bestMove(board,2);if(best)board.move(best);g.busy=false;drawGame();},240);});}
function evaluateBoard(board){const value={p:100,n:320,b:330,r:500,q:900,k:0};return board.board().flat().reduce((sum,p)=>sum+(p?(p.color==='w'?1:-1)*value[p.type]:0),0);}
function bestMove(board,depth){const moves=board.moves({verbose:true});let best=null,score=Infinity;for(const move of moves){board.move(move);const result=searchMove(board,depth-1,-Infinity,Infinity);board.undo();if(result<score){score=result;best={from:move.from,to:move.to,promotion:move.promotion};}}return best;}
function searchMove(board,depth,alpha,beta){if(board.isCheckmate())return board.turn()==='w'?-100000-depth:100000+depth;if(board.isDraw())return 0;if(depth===0)return evaluateBoard(board);const maximizing=board.turn()==='w';let result=maximizing?-Infinity:Infinity;for(const m of board.moves()){board.move(m);const score=searchMove(board,depth-1,alpha,beta);board.undo();if(maximizing){result=Math.max(result,score);alpha=Math.max(alpha,result);}else{result=Math.min(result,score);beta=Math.min(beta,result);}if(beta<=alpha)break;}return result;}

render();

import './reference.css';
